class ArrayStack:
    def __init__(self, capacity=10):
        self.capacity = capacity
        self.array = [None] * capacity
        self.top = -1

    def is_empty(self):
        return self.top == -1

    def is_full(self):
        return self.top == self.capacity - 1

    def push(self, item):
        if self.is_full():
            raise IndexError('Stack Overflow: 스택 포화 상태')
        self.top += 1
        self.array[self.top] = item

    def pop(self):
        if self.is_empty():
            raise IndexError('Stack Underflow: 스택 공백 상태')
        item = self.array[self.top]
        self.array[self.top] = None
        self.top -= 1
        return item

    def peek(self):
        if self.is_empty():
            raise IndexError('Stack Underflow: 스택 공백 상태')
        return self.array[self.top]

    def size(self):
        return self.top + 1

def is_empty(self):
    return self.front == self.rear

def is_full(self):
    return (self.rear + 1) % self.capacity == self.front

def enqueue(self, item):
    if self.is_full():
        raise IndexError('Queue Overflow')
    self.rear = (self.rear + 1) % self.capacity
    self.array[self.rear] = item

def dequeue(self):
    if self.is_empty():
        raise IndexError('Queue Underflow')
    self.front = (self.front + 1) % self.capacity
    item = self.array[self.front]
    self.array[self.front] = None
    return item

def add_front(self, item):
    if self.is_full():
        raise IndexError('Deque Overflow')
    self.array[self.front] = item
    self.front = (self.front - 1 + self.capacity) % self.capacity

def delete_rear(self):
    if self.is_empty():
        raise IndexError('Deque Underflow')
    item = self.array[self.rear]
    self.array[self.rear] = None
    self.rear = (self.rear - 1 + self.capacity) % self.capacity
    return item

def is_palindrome(text):
    dq = CircularDeque(len(text) + 1)
    for ch in text:
        dq.add_rear(ch)
    while dq.size() > 1:
        first = dq.delete_front()
        last = dq.delete_rear()
        if first != last:
