class Node:
    def __init__(self, data, link=None):
        self.data = data
        self.link = link

class LinkedList:
    def __init__(self):
        self.head = None

    def insert(self, pos, elem):
        new_node = Node(elem)
        if pos == 0:
            new_node.link = self.head
            self.head = new_node
        else:
            prev = self.get_node(pos - 1)
            if prev is None:
                raise IndexError('Invalid position')
            new_node.link = prev.link  # 새 노드의 링크를 먼저 후속 노드에 연결!
            prev.link = new_node       # 이후 선행 노드가 새 노드를 가리킴

def hanoi_tower(n, fr, to, aux):
    if n == 1:
        print(f'원반 1: {fr} -> {to}')
    else:
        hanoi_tower(n - 1, fr, aux, to)      # 1. n-1개 원반을 fr에서 aux로
        print(f'원반 {n}: {fr} -> {to}')       # 2. 가장 큰 n번 원반을 to로
        hanoi_tower(n - 1, aux, to, fr)      # 3. n-1개 원반을 aux에서 to로

동작 원리:
- enqueue: 새 원소를 입력 스택 S1에 무조건 푸시(push)한다.
- dequeue: 출력 스택 S2가 비어있지 않다면 S2에서 팝(pop)하여 반환한다. 만약 S2가 비어있다면 S1의 모든 원소를 하나씩 꺼내어 S2에 푸시(이 과정에서 역순이 되어 FIFO 순서가 됨)한 후 S2에서 팝하여 반환한다.

