S1 = queue.LifoQueue()
S2 = queue.LifoQueue()

def enqueue(val):
    S1.put(val)

def dequeue():
    if S2.empty():
        if S1.empty():
            return None  # Underflow 방어
        while not S1.empty():
            S2.put(S1.get())
    return S2.get()
