def enqueue(self, item):
    pos = len(self.items) - 1
    # 뒤에서부터 순회하며 item보다 큰 원소는 건너뜀
    while pos >= 0 and self.items[pos] > item:
        pos -= 1
    # 올바른 위치에 삽입 (정렬 상태 유지)
    self.items.insert(pos + 1, item)

def dequeue(self):
    if not self.isEmpty():
        return self.items.pop(-1)  # 맨 뒤 최댓값 O(1)에 삭제
